CREATE OR REPLACE FUNCTION public.auditar_numero_socio() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_name text; affected uuid; BEGIN IF NEW.numero_socio IS NOT DISTINCT FROM OLD.numero_socio THEN RETURN NEW; END IF; IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF NEW.numero_socio IS NULL OR NEW.numero_socio<1 THEN RAISE EXCEPTION 'Indica un nº de soci@ válido'; END IF; PERFORM pg_advisory_xact_lock(72112611); SELECT nombre INTO owner_name FROM public.socios WHERE numero_socio=NEW.numero_socio AND id<>OLD.id; IF FOUND THEN RAISE EXCEPTION 'El nº % ya es de %',NEW.numero_socio,owner_name; END IF; SELECT user_id INTO affected FROM public.usuario_roles WHERE socio_id=OLD.id AND user_id IS NOT NULL LIMIT 1; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(auth.uid(),affected,'cambiar_numero_socio',OLD.nombre||' · '||OLD.numero_socio||' → '||NEW.numero_socio||' · id '||OLD.id); RETURN NEW; END $$;
CREATE TRIGGER auditar_numero_socio BEFORE UPDATE OF numero_socio ON public.socios FOR EACH ROW EXECUTE FUNCTION public.auditar_numero_socio();
CREATE OR REPLACE FUNCTION public.editar_socio_ficha(p_id uuid,p_nombre text,p_email text,p_telefono text,p_numero bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF p_numero IS NULL OR p_numero<1 THEN RAISE EXCEPTION 'Indica un nº de soci@ válido'; END IF; PERFORM pg_advisory_xact_lock(72112611); PERFORM public.editar_socio_datos(p_id,p_nombre,p_email,p_telefono); UPDATE public.socios SET numero_socio=p_numero WHERE id=p_id; END $$;
REVOKE ALL ON FUNCTION public.editar_socio_ficha(uuid,text,text,text,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.editar_socio_ficha(uuid,text,text,text,bigint) TO authenticated;
REVOKE ALL ON FUNCTION public.auditar_numero_socio() FROM PUBLIC,anon,authenticated;